/**
 * WIND ENERGY / CONCEPT 09 — Wind-Powered Agriculture
 * 25 seconds | 3 scenes | 16:9 | 4K / 2K / FHD | 60 fps
 * Pure Canvas 2D. No external assets, DOM, dependencies, glow or wall clocks.
 * All background elements and the camera remain static within every scene.
 * Set the external video encoder to 100 Mbps when exporting the final video.
 */
const WindPoweredAgriculture = (() => {
  const TAU = Math.PI * 2;
  const FONT = 'Arial, Helvetica, "Nimbus Sans", "DejaVu Sans", sans-serif';
  const C = {
    ink: '#3d5d51', outline: '#66826c', paper: '#f6f7ee', white: '#fcfcf5',
    teal: '#3c817e', mint: '#b6d6c6', muted: '#627b7d', sand: '#e5dac0'
  };
  const clamp = v => Math.max(0, Math.min(1, v));
  const ease = v => { v = clamp(v); return v*v*v*(v*(v*6-15)+10); };
  const mix = (a,b,p) => a+(b-a)*p;
  const fract = v => v-Math.floor(v);
  const sin = (clock, n=1, phase=0) => Math.sin(TAU*(clock.loopT/25*n+phase));

  function rounded(ctx,x,y,w,h,r,fill,stroke=null,lw=2) {
    r=Math.min(r,w*.5,h*.5);
    ctx.beginPath();
    ctx.moveTo(x+r,y); ctx.lineTo(x+w-r,y); ctx.quadraticCurveTo(x+w,y,x+w,y+r);
    ctx.lineTo(x+w,y+h-r); ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);
    ctx.lineTo(x+r,y+h); ctx.quadraticCurveTo(x,y+h,x,y+h-r);
    ctx.lineTo(x,y+r); ctx.quadraticCurveTo(x,y,x+r,y); ctx.closePath();
    if(fill){ctx.fillStyle=fill;ctx.fill();}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();}
  }
  function line(ctx,points,color,lw=2) {
    if(points.length<2)return;
    ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);
    for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);
    ctx.strokeStyle=color;ctx.lineWidth=lw;ctx.stroke();
  }
  function polygon(ctx,points,fill,stroke=null,lw=2) {
    ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);
    for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);
    ctx.closePath();
    if(fill){ctx.fillStyle=fill;ctx.fill();}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();}
  }
  function ellipse(ctx,x,y,rx,ry,fill,stroke=null,lw=2) {
    ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,TAU);
    if(fill){ctx.fillStyle=fill;ctx.fill();}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();}
  }
  function label(ctx,txt,x,y,size=16,color=C.ink,weight=500,align='left',maxWidth=Infinity) {
    ctx.textAlign=align;ctx.textBaseline='alphabetic';
    let actual=size;ctx.font=weight+' '+actual+'px '+FONT;
    if(Number.isFinite(maxWidth)) {
      const measured=ctx.measureText(txt).width;
      if(measured>maxWidth){actual=size*maxWidth/measured;ctx.font=weight+' '+actual+'px '+FONT;}
    }
    ctx.fillStyle=color;ctx.fillText(txt,x,y);
  }
  function tracked(ctx,txt,x,y,size=13,spacing=2.4,color=C.ink) {
    ctx.font='600 '+size+'px '+FONT;ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.fillStyle=color;
    for(const ch of txt){ctx.fillText(ch,x,y);x+=ctx.measureText(ch).width+spacing;}
  }
  function gradient(ctx,x0,y0,x1,y1,stops) {
    const g=ctx.createLinearGradient(x0,y0,x1,y1);
    for(const [p,c] of stops)g.addColorStop(p,c);
    return g;
  }
  function cubic(a,b,c,d,steps=36) {
    const points=[];
    for(let i=0;i<=steps;i++) {
      const p=i/steps,q=1-p;
      points.push([q*q*q*a[0]+3*q*q*p*b[0]+3*q*p*p*c[0]+p*p*p*d[0],
        q*q*q*a[1]+3*q*q*p*b[1]+3*q*p*p*c[1]+p*p*p*d[1]]);
    }
    return points;
  }
  function joinCurves(...curves) {return curves.flatMap((p,i)=>i?p.slice(1):p);}
  function packets(ctx,points,clock,count=5,cycles=2,color='#f7f6de',radius=4) {
    const lengths=[0];let total=0;
    for(let i=1;i<points.length;i++){total+=Math.hypot(points[i][0]-points[i-1][0],points[i][1]-points[i-1][1]);lengths.push(total);}
    if(!total)return;
    for(let k=0;k<count;k++) {
      const p=fract(clock.loopT/25*cycles+k/count),distance=p*total;
      let j=1;while(j<lengths.length-1&&lengths[j]<distance)j++;
      const u=(distance-lengths[j-1])/(lengths[j]-lengths[j-1]||1);
      const alpha=ease(p/.055)*ease((1-p)/.055);
      ctx.save();ctx.globalAlpha*=alpha;
      ellipse(ctx,mix(points[j-1][0],points[j][0],u),mix(points[j-1][1],points[j][1],u),radius,radius,color);
      ctx.restore();
    }
  }
  function cable(ctx,points,clock,options={}) {
    line(ctx,points,options.edge||'#eaf0df',options.width||8);
    line(ctx,points,options.color||'#417e77',(options.width||8)-3);
    packets(ctx,points,clock,options.count||6,options.cycles||2,options.packet||'#f6edbd',options.radius||3.6);
  }
  function turbine(ctx,x,baseY,height,radius,clock,seed=0,options={}) {
    const hubY=baseY-height;
    ctx.save();
    if(!options.marine)ellipse(ctx,x+2,baseY+4,height*.095,height*.018,'rgba(49,91,77,.12)');
    const tower=gradient(ctx,x-height*.04,0,x+height*.04,0,[[0,'#dae6df'],[.5,'#fafbf2'],[1,'#c0d1cc']]);
    ctx.beginPath();ctx.moveTo(x-height*.019,hubY+1);ctx.lineTo(x+height*.019,hubY+1);
    ctx.lineTo(x+height*.042,baseY);ctx.quadraticCurveTo(x,baseY+height*.011,x-height*.042,baseY);ctx.closePath();
    ctx.fillStyle=tower;ctx.fill();ctx.lineWidth=2;ctx.strokeStyle=C.outline;ctx.stroke();
    line(ctx,[[x+height*.017,hubY+height*.13],[x+height*.027,baseY-height*.04]],'rgba(83,118,114,.28)',1.3);
    rounded(ctx,x-height*.049,hubY-height*.031,height*.135,height*.065,height*.022,'#d6e4dd',C.outline,1.8);
    if(height>200&&!options.marine)rounded(ctx,x-height*.014,baseY-height*.084,height*.028,height*.067,2,'#b8ccc3',C.outline,1.2);
    ctx.save();ctx.translate(x,hubY);ctx.rotate(TAU*(clock.loopT/25*2+seed));
    for(let j=0;j<3;j++) {
      ctx.save();ctx.rotate(j*TAU/3);ctx.beginPath();
      ctx.moveTo(-radius*.037,-radius*.055);
      ctx.bezierCurveTo(-radius*.072,-radius*.29,-radius*.032,-radius*.70,radius*.031,-radius*.985);
      ctx.quadraticCurveTo(radius*.045,-radius*1.021,radius*.061,-radius*.977);
      ctx.bezierCurveTo(radius*.092,-radius*.70,radius*.116,-radius*.28,radius*.055,-radius*.095);
      ctx.quadraticCurveTo(radius*.026,-radius*.045,-radius*.037,-radius*.055);ctx.closePath();
      ctx.fillStyle=j===1?'#e5ede5':'#fbfcf4';ctx.fill();ctx.strokeStyle=C.outline;ctx.lineWidth=1.8;ctx.stroke();
      ctx.restore();
    }
    ctx.restore();
    ellipse(ctx,x,hubY,radius*.081,radius*.081,'#f5f8ee',C.outline,2);
    ellipse(ctx,x,hubY,radius*.026,radius*.026,'#8daaa3');
    if(options.marine) {
      rounded(ctx,x-12,baseY-4,24,17,3,'#e1c77c',C.outline,1.8);
    } else {
      rounded(ctx,x-height*.054,baseY-2,height*.108,height*.017,2,'#bccfc0',C.outline,1.2);
    }
    ctx.restore();
  }
  function tree(ctx,x,y,s=1,color='#89ae91') {
    line(ctx,[[x,y],[x,y-28*s]],'#5c7b69',2*s);
    ctx.beginPath();ctx.moveTo(x,y-58*s);ctx.bezierCurveTo(x+21*s,y-48*s,x+22*s,y-20*s,x+1*s,y-20*s);
    ctx.bezierCurveTo(x-20*s,y-19*s,x-19*s,y-45*s,x,y-58*s);ctx.closePath();
    ctx.fillStyle=color;ctx.fill();ctx.strokeStyle='#5d8573';ctx.lineWidth=1.5*s;ctx.stroke();
  }
  function station(ctx,x,baseY,s=1) {
    ctx.save();ctx.translate(x,baseY);ctx.scale(s,s);
    rounded(ctx,-111,-4,222,11,3,'#a6bcb0',C.outline,1.5);
    rounded(ctx,-95,-80,107,77,5,'#eaf0df',C.outline,2);
    polygon(ctx,[[-102,-80],[-87,-99],[7,-99],[20,-80]],'#a2bbb3',C.outline,2);
    rounded(ctx,-79,-59,31,32,3,'#a4c3bd',C.outline,1.5);
    line(ctx,[[-63,-59],[-63,-27]],'#6a928b',1.3);
    rounded(ctx,-27,-53,22,50,2,'#b8cbc0',C.outline,1.5);
    rounded(ctx,37,-48,55,44,5,'#99b4a5',C.outline,2);
    for(let i=0;i<5;i++)line(ctx,[[45+i*9,-39],[45+i*9,-12]],'#5d8279',1.5);
    for(let i=0;i<3;i++) {
      const xx=46+i*19;line(ctx,[[xx,-48],[xx,-72]],C.outline,2.5);
      for(let k=0;k<3;k++)rounded(ctx,xx-4,-68+k*5,8,3,1,'#dae7d7',C.outline,1);
    }
    line(ctx,[[21,-87],[107,-87]],C.outline,3);
    line(ctx,[[28,-87],[28,-6]],C.outline,3);
    line(ctx,[[102,-87],[102,-6]],C.outline,3);
    line(ctx,[[28,-87],[44,-71]],C.outline,1.5);line(ctx,[[102,-87],[87,-71]],C.outline,1.5);
    ctx.restore();
  }
  function house(ctx,x,baseY,s=1,fill='#f2eddb',roof='#608b83') {
    ctx.save();ctx.translate(x,baseY);ctx.scale(s,s);
    rounded(ctx,-43,-59,86,58,3,fill,C.outline,1.7);
    polygon(ctx,[[-52,-59],[0,-96],[52,-59]],roof,C.outline,2);
    rounded(ctx,-28,-44,18,19,2,'#b0cec6',C.outline,1.4);
    line(ctx,[[-19,-43],[-19,-26]],'#6e9890',1);
    rounded(ctx,13,-36,18,35,2,'#9bb7a6',C.outline,1.4);
    line(ctx,[[-46,1],[47,1]],'#7d9f86',2);ctx.restore();
  }
  const DARK = false;
  const UI = {"ink": "#3d5d51", "muted": "#70876e", "panel": "#edf1e4", "border": "#9fb59b", "accent": "#78966c", "track": "#c9d8bf", "pale": "#dde7d1", "warm": "#c5b781"};
  function panel(ctx,x,y,w,h,title=null) {
    rounded(ctx,x,y,w,h,16,UI.panel,UI.border,1.6);
    if(title)tracked(ctx,title,x+26,y+39,12,1.55,UI.muted);
  }
  function badge(ctx,text,x,y,w,active=true) {
    rounded(ctx,x,y,w,30,8,UI.pale,UI.border,1.2);
    if(active)ellipse(ctx,x+15,y+15,3.5,3.5,UI.accent);
    label(ctx,text,x+(active?27:14),y+20,11,UI.ink,600,'left',w-(active?40:27));
  }
  function header(ctx,title,subtitle,index) {
    tracked(ctx,'WIND ENERGY',100,80,13,2.8,UI.ink);
    line(ctx,[[100,95],[151,95]],UI.accent,2);
    label(ctx,title,98,150,50,UI.ink,600,'left',1170);
    label(ctx,subtitle,101,186,17,UI.muted,400,'left',1145);
    label(ctx,'0'+(index+1)+' / 03',1498,80,14,UI.muted,500,'right');
  }
  function footer(ctx,text,index,clock) {
    for(let i=0;i<3;i++) {
      const x=100+i*61;
      rounded(ctx,x,845,47,3,1.5,UI.track);
      if(i<index)rounded(ctx,x,845,47,3,1.5,UI.accent);
      if(i===index&&clock.sceneProgress>.00001)rounded(ctx,x,845,Math.max(.05,47*clamp(clock.sceneProgress/.88)),3,1.5,UI.accent);
    }
    tracked(ctx,text,316,852,11,1.65,UI.muted);
  }
  function gear(ctx,x,y,outerR,teeth,angle,fill) {
    ctx.save();ctx.translate(x,y);ctx.rotate(angle);
    const rootR=outerR*(teeth-2.5)/(teeth+2),step=TAU/teeth;
    const fractions=[0,.15,.28,.60,.73,1];
    ctx.beginPath();
    for(let i=0;i<teeth;i++)for(let k=0;k<fractions.length;k++) {
      const a=(i+fractions[k])*step,r=(k===2||k===3)?outerR:rootR;
      const xx=Math.cos(a)*r,yy=Math.sin(a)*r;
      if(i===0&&k===0)ctx.moveTo(xx,yy);else ctx.lineTo(xx,yy);
    }
    ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle='#577582';ctx.lineWidth=1.7;ctx.stroke();
    ellipse(ctx,0,0,outerR*.54,outerR*.54,'#edf3ed','#577582',1.5);
    for(let i=0;i<4;i++) {
      const a=i*TAU/4;
      line(ctx,[[Math.cos(a)*outerR*.18,Math.sin(a)*outerR*.18],[Math.cos(a)*outerR*.49,Math.sin(a)*outerR*.49]],'#729299',3.5);
    }
    ellipse(ctx,0,0,outerR*.18,outerR*.18,'#b5cacc','#577582',1.4);
    ctx.restore();
  }
  function coilRotor(ctx,x,y,clock,r=56) {
    ellipse(ctx,x,y,r+16,r+16,'#d1e1df','#5b7c87',2);
    for(let i=0;i<12;i++) {
      ctx.save();ctx.translate(x,y);ctx.rotate(i*TAU/12);
      rounded(ctx,-5,-r-11,10,16,2,'#8eaaa9','#5b7c87',1.2);ctx.restore();
    }
    ctx.save();ctx.translate(x,y);ctx.rotate(-TAU*3*clock.loopT/25);
    ellipse(ctx,0,0,r-3,r-3,'#f0f4eb','#5b7c87',1.8);
    for(let i=0;i<6;i++) {
      const a=i*TAU/6;
      line(ctx,[[Math.cos(a)*11,Math.sin(a)*11],[Math.cos(a)*(r-14),Math.sin(a)*(r-14)]],'#8eaba5',6);
    }
    ellipse(ctx,0,0,13,13,'#abc3c2','#577582',1.8);ctx.restore();
  }
  function chart(ctx,x,y,w,h,clock,offset=0,axes=true) {
    for(let i=0;i<=4;i++)line(ctx,[[x,y+h*i/4],[x+w,y+h*i/4]],UI.track,1);
    for(let i=0;i<=4;i++)line(ctx,[[x+w*i/4,y],[x+w*i/4,y+h]],UI.track,1);
    const points=[];
    for(let i=0;i<=96;i++) {
      const u=i/96,p=clock.loopT/25;
      const value=.53+.15*Math.sin(TAU*(u*1.2-p+offset))+.065*Math.cos(TAU*(u*2.4-p*2+offset));
      points.push([x+u*w,y+(1-value)*h]);
    }
    ctx.beginPath();ctx.moveTo(x,y+h);for(const pt of points)ctx.lineTo(pt[0],pt[1]);
    ctx.lineTo(x+w,y+h);ctx.closePath();
    ctx.fillStyle=gradient(ctx,0,y,0,y+h,DARK?[[0,'rgba(173,205,191,.15)'],[1,'rgba(173,205,191,.025)']]:[[0,'rgba(86,143,149,.16)'],[1,'rgba(86,143,149,.025)']]);ctx.fill();
    line(ctx,points,UI.accent,2.5);
    const last=points[points.length-1];ellipse(ctx,last[0],last[1],4,4,UI.accent);
    if(axes) {
      label(ctx,'1.0',x-12,y+4,10,UI.muted,400,'right');
      label(ctx,'0.5',x-12,y+h*.5+4,10,UI.muted,400,'right');
      label(ctx,'0.0',x-12,y+h+4,10,UI.muted,400,'right');
      label(ctx,'RECENT',x,y+h+23,10,UI.muted,500);
      label(ctx,'CURRENT',x+w,y+h+23,10,UI.muted,500,'right');
    }
  }
  function thinArrow(ctx,x,y,color=UI.accent) {
    line(ctx,[[x-9,y],[x+9,y]],color,1.8);
    line(ctx,[[x+3,y-5],[x+9,y],[x+3,y+5]],color,1.8);
  }
  function energyStages(ctx,x,y,width,clock,words) {
    const positions=[x,x+width*.5,x+width];
    line(ctx,[[positions[0]+13,y],[positions[2]-13,y]],UI.track,2);
    packets(ctx,[[positions[0]+13,y],[positions[2]-13,y]],clock,5,2,UI.accent,3.2);
    for(let i=0;i<3;i++) {
      ellipse(ctx,positions[i],y,10,10,UI.pale,UI.accent,1.7);
      label(ctx,words[i],positions[i],y+33,11,UI.ink,600,'center',width*.36);
    }
  }
  function transition(ctx,clock,renderScene,renderChrome) {
    renderScene(ctx,clock.currentScene,clock,clock.sceneProgress);
    const transitionStart=.88;
    if(clock.sceneProgress<=transitionStart){renderChrome(ctx,clock.currentScene,clock);return;}
    const p=ease((clock.sceneProgress-transitionStart)/(1-transitionStart));
    const edge=1600*(1-p);
    const next=(clock.currentScene+1)%3;
    const nextClock={...clock,currentScene:next,sceneProgress:0};
    ctx.save();ctx.beginPath();ctx.rect(edge,0,1600-edge+1,900);ctx.clip();
    renderScene(ctx,next,nextClock,0);ctx.restore();
    // An opaque clipped reveal avoids double images during all three scene handoffs.
    if(p>0&&p<1) {
      const a=.7*ease(p/.06)*ease((1-p)/.06);
      line(ctx,[[edge,0],[edge,900]],'rgba(248,250,239,'+a+')',2);
    }
    // Typography changes outside the scene mask, with no overlapping or split words.
    if(p<.48) {
      ctx.save();ctx.globalAlpha*=1-ease(p/.48);
      renderChrome(ctx,clock.currentScene,clock);ctx.restore();
    } else if(p>.52) {
      ctx.save();ctx.globalAlpha*=ease((p-.52)/.48);
      renderChrome(ctx,next,nextClock);ctx.restore();
    }
  }

  function background(ctx) {
    ctx.fillStyle=gradient(ctx,0,0,1600,900,[[0,'#e3edf0'],[.52,'#dfe8d9'],[1,'#eee5cb']]);
    ctx.fillRect(0,0,1600,900);
    ctx.beginPath();ctx.moveTo(938,-10);ctx.bezierCurveTo(1120,134,1380,73,1610,221);
    ctx.lineTo(1610,-10);ctx.closePath();ctx.fillStyle='#d0dfdf';ctx.fill();
    ctx.beginPath();ctx.moveTo(-10,694);ctx.bezierCurveTo(314,617,552,698,848,663);
    ctx.bezierCurveTo(1120,627,1374,651,1610,602);ctx.lineTo(1610,910);ctx.lineTo(-10,910);ctx.closePath();
    ctx.fillStyle='#d0ddc6';ctx.fill();
    ctx.beginPath();ctx.moveTo(-10,795);ctx.bezierCurveTo(472,746,1040,878,1610,753);
    ctx.lineTo(1610,910);ctx.lineTo(-10,910);ctx.closePath();ctx.fillStyle='#c6d5b9';ctx.fill();
    line(ctx,[[100,821],[1500,821]],'#a5b798',1);
    for(let i=0;i<15;i++)line(ctx,[[100+i*100,809],[100+i*100,821]],'#a5b798',1);
    // Gradient, terrain, vegetation and registration marks never depend on time.
  }
  function water(ctx,points,clock,count=5) {
    cable(ctx,points,clock,{edge:'#c7dcd9',color:'#6598a3',packet:'#f1f6ed',width:8,count,radius:3,cycles:2});
  }
  function electricity(ctx,points,clock,count=5) {
    cable(ctx,points,clock,{edge:'#dce4c9',color:'#708f66',packet:'#f4e8af',width:7,count,radius:2.8,cycles:2});
  }
  function plant(ctx,x,y,s=1) {
    line(ctx,[[x,y],[x,y-13*s]],'#6c8b57',1.3*s);
    ctx.beginPath();ctx.moveTo(x,y-5*s);
    ctx.bezierCurveTo(x-10*s,y-4*s,x-12*s,y-12*s,x-12*s,y-14*s);
    ctx.bezierCurveTo(x-4*s,y-15*s,x-1*s,y-9*s,x,y-5*s);
    ctx.moveTo(x,y-8*s);ctx.bezierCurveTo(x+2*s,y-16*s,x+9*s,y-18*s,x+12*s,y-17*s);
    ctx.bezierCurveTo(x+12*s,y-11*s,x+6*s,y-7*s,x,y-8*s);
    ctx.fillStyle='#8faa6f';ctx.fill();
  }
  function plot(ctx,x,y,w,h,columns=8) {
    rounded(ctx,x,y,w,h,8,'#d6d7b6','#9baa86',1.4);
    const rows=h>58?3:2,step=h/(rows+1);
    for(let r=0;r<rows;r++) {
      const yy=y+step*(r+1)+4;
      line(ctx,[[x+13,yy+4],[x+w-13,yy+4]],'#bdc29c',1);
      for(let k=0;k<columns;k++)plant(ctx,x+22+k*(w-44)/(columns-1),yy,.64);
    }
  }
  function greenhouse(ctx,x,baseY,s=1) {
    ctx.save();ctx.translate(x,baseY);ctx.scale(s,s);
    rounded(ctx,-180,-4,360,10,3,'#adc0a1',C.outline,1.4);
    rounded(ctx,-175,-105,350,103,3,gradient(ctx,0,-106,0,0,[[0,'#d4e6df'],[1,'#bfd4bc']]),C.outline,1.8);
    polygon(ctx,[[-188,-105],[0,-185],[188,-105]],'#e8f1e8',C.outline,2);
    for(let k=0;k<5;k++) {
      const xx=-145+k*72.5;
      plant(ctx,xx,-18,1.5);
    }
    for(let i=0;i<7;i++) {
      const xx=-150+i*50;
      line(ctx,[[xx,-102],[xx,-5]],'#87a99e',1.4);
      const roofY=-185+80*Math.abs(xx)/188;
      line(ctx,[[xx,-105],[xx,roofY]],'#a4c0b3',1.3);
    }
    line(ctx,[[-174,-61],[174,-61]],'#93b0a1',1.5);
    line(ctx,[[-124,-132],[124,-132]],'#b6cabc',1.1);
