/** Deterministic render entry point. time is already measured in SECONDS. */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1600, height / 900, minSide / 900);
  if (!ctx || !Number.isFinite(t) || !Number.isFinite(scale) || scale <= 0) return;
  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'transparent';
    ctx.filter = 'none';
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.miterLimit = 2;
    const background = ctx.createLinearGradient(0, 0, width, height);
    background.addColorStop(0, '#e1eaf0');
    background.addColorStop(1, '#c4d4c0');
    ctx.fillStyle = background;
    ctx.fillRect(0, 0, width, height);
    ctx.translate((width - 1600 * scale) / 2, (height - 900 * scale) / 2);
    ctx.scale(scale, scale);
    ctx.beginPath();ctx.rect(0, 0, 1600, 900);ctx.clip();
    SmartWindOperations.render(ctx, { t, duration, loopT, currentScene, sceneProgress });
  } finally {
    ctx.restore();
  }
}

// Export settings are metadata for the host renderer, not a video encoder.
draw.duration = 25;
draw.sceneCount = 3;
draw.fps = 60;
draw.width = 3840;
draw.height = 2160;
draw.bitrate = 100000000;
draw.backgroundStatic = true;
draw.cameraMotion = false;
draw.exportSettings = Object.freeze({
  width: 3840, height: 2160, fps: 60, duration: 25,
  bitrate: 100000000, minBitrate: 100000000, bitrateMode: 'constant'
});

/**
 * WIND ENERGY — Wind Valley
 * 25 seconds | 3 scenes | seamless loop | 16:9 | 4K / 2K / FHD
 * Pure Canvas 2D. No DOM, external assets, dependencies, glow or wall clocks.
 * Render at 60 fps; configure the external video encoder for 100 Mbps.
