    ctx.lineTo(1640,-20);ctx.closePath();ctx.fillStyle=marine?'rgba(174,189,215,.18)':'rgba(185,209,203,.21)';ctx.fill();
    ellipse(ctx,1373,169,48,48,marine?'#f1e9d5':'#f3e7c9');
